public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> permutations = new ArrayList<>();
    if (nums.length == 1) {
        permutations.add(Arrays.asList(nums[0]));
        return permutations;
    }
    for (int i = 0; i < nums.length; i++) {
        int num = nums[i];
        List<Integer> remainingNums = new ArrayList<>(nums);
        remainingNums.remove(i);
        List<List<Integer>> recursivePermutations = permute(remainingNums.toArray(new int[remainingNums.size()]));
        for (List<Integer> recursivePermutation : recursivePermutations) {
            List<Integer> permutation = new ArrayList<>(recursivePermutation);
            permutation.add(num);
            permutations.add(permutation);
        }
    }
    return permutations;
}

