public int search(int[] nums, int target) {

  // check if the array is empty
  if (nums.length == 0) {
    return -1;
  }

  // initialize the left and right pointers
  int left = 0;
  int right = nums.length - 1;

  // loop until the pointers meet
  while (left <= right) {

    // find the middle index
    int mid = (left + right) / 2;

    // check if the middle element is the target
    if (nums[mid] == target) {
      return mid;
    }

    // check if the left half is sorted
    if (nums[left] <= nums[mid]) {

      // if the target is in the left half, move the right pointer
      if (nums[left] <= target && target < nums[mid]) {
        right = mid - 1;
      } else {
        left = mid + 1;
      }

    } else {

      // if the target is in the right half, move the left pointer
      if (nums[mid] < target && target <= nums[right]) {
        left = mid + 1;
      } else {
        right = mid - 1;
      }
    }
  }

  // if the target is not found, return -1
  return -1;
}

public double trimMean(int[] arr) {
    // Calculate the mean of the array
    double mean = 0;
    for (int i = 0; i < arr.length; i++) {
        mean += arr[i];
    }
    mean /= arr.length;

    // Calculate the 5% cutoff points
    double min_cutoff = mean - 0.05 * mean;
    double max_cutoff = mean + 0.05 * mean;

    // Remove the smallest 5% and largest 5% values
    int num_removed = 0;
    for (int i = 0; i < arr.length; i++) {
        if (arr[i] < min_cutoff || arr[i] > max_cutoff) {
            num_removed++;
            arr[i] = Integer.MAX_VALUE;
        }
    }

    // Recalculate the mean of the remaining values
    double new_mean = 0;
    for (int i = 0; i < arr.length; i++) {
        if (arr[i] != Integer.MAX_VALUE) {
            new_mean += arr[i];
        }
    }
    new_mean /= arr.length - num_removed;

    return new_mean;
}

