        return 0;
    }

    int rows = mat.length;
    int cols = mat[0].length;
    int maxLength = 0;

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (mat[i][j] == 1) {
                int currentLength = 1;
                while (i + currentLength < rows && j + currentLength < cols && mat[i + currentLength][j + currentLength] == 1) {
                    currentLength++;
                }
                maxLength = Math.max(maxLength, currentLength);
            }
        }
    }

    return maxLength;
}

