    int a1 = x2 - x1;
    int b1 = y2 - y1;
    int a2 = x3 - x1;
    int b2 = y3 - y1;
    return a1 * b2 == a2 * b1;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n should be positive");
    }
    int count = 0;
    int i = 1;
    while (count < n) {
        if (isUglyNumber(i)) {
            count++;
        }
        i++;
    }
    return i - 1;
}

public static int calculateEnergy(String s) {
    int maxLength = 0;
    char currentChar = '\0';
    int currentLength = 0;
    for (char c : s.toCharArray()) {
        if (c != currentChar) {
            maxLength = Math.max(maxLength, currentLength);
            currentLength = 0;
            currentChar = c;
        }
        currentLength++;
    }
    return maxLength;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    for (int i = 1; i <= n; i++) {
        String str = String.valueOf(i);
        int index = Collections.binarySearch(result, str);
        if (index < 0) {
            index = -index - 1;
        }
        result.add(index, i);
    }
    return result;
}

public static int calculateUniqueSum(int[] nums) {
    Set<Integer> uniqueNums = new HashSet<>();
    int sum = 0;
    for (int num : nums) {
        if (uniqueNums.add(num)) {
            sum += num;
        }
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    int count = 0;
    while (n > 0) {
        int root = (int) Math.sqrt(n);
        count++;
        n -= root * root;
    }
    return count;
}

public static String reverseWords(String s) {
    String[] words = s.split(" ");
    StringBuilder sb = new StringBuilder();
    for (String word : words) {
        sb.append(reverse(word));
        sb.append(" ");
    }
    return sb.toString().trim();
}
